import { supabase } from './supabase.js';
import { openMemberProfile } from './member-profile-card.js';

const $=selector=>document.querySelector(selector),esc=(value='')=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'),norm=(value='')=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const labels={announcement:'Annonce',discussion:'Discussion',question:'Question',success:'Réussite',resource:'Ressource'};
const feed=$('#posts-feed'),dialog=$('#post-thread-dialog'),commentInput=$('#post-comment-content'),mentionSuggestions=$('#post-mention-suggestions');let user,ownProfile,posts=[],profiles=new Map(),filter='all',activePost,room,allProfilesLoaded=false;
let postImagePreviewUrl='';
const date=value=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const profile=id=>profiles.get(id)||{display_name:'Membre STOA',avatar_url:null};
const avatar=(item,id)=>item.avatar_url?`<button class="post-avatar has-image" type="button" data-member-profile="${id}" style="background-image:url('${esc(item.avatar_url)}')" aria-label="Voir le profil de ${esc(item.display_name)}"></button>`:`<button class="post-avatar" type="button" data-member-profile="${id}" aria-label="Voir le profil de ${esc(item.display_name)}">${esc((item.display_name||'S')[0].toUpperCase())}</button>`;

async function loadProfiles(ids){const missing=[...new Set(ids.filter(Boolean))].filter(id=>!profiles.has(id));if(!missing.length)return;const {data}=await supabase.rpc('get_community_profiles',{profile_ids:missing});(data||[]).forEach(item=>profiles.set(item.id,item));}
async function loadAllProfiles(){if(allProfilesLoaded)return;const {data,error}=await supabase.rpc('get_community_profiles',{profile_ids:null});if(!error){(data||[]).forEach(item=>profiles.set(item.id,item));allProfilesLoaded=true;}}
function rich(value=''){const expression=/@[A-Za-z0-9_.;-]{2,32}/g;let output='',cursor=0;for(const match of String(value).matchAll(expression)){output+=esc(value.slice(cursor,match.index)).replaceAll('\n','<br>');output+=`<button class="post-inline-mention" type="button" data-mention-username="${esc(match[0].slice(1))}">${esc(match[0])}</button>`;cursor=match.index+match[0].length;}return output+esc(value.slice(cursor)).replaceAll('\n','<br>');}
async function loadPosts(){
  const {data,error}=await supabase.from('community_posts').select('*,community_post_comments(count),community_post_reactions(id,user_id,emoji)').order('pinned_at',{ascending:false,nullsFirst:false}).order('created_at',{ascending:false});
  if(error){feed.innerHTML=`<div class="posts-empty"><h2>Le fil est momentanément indisponible.</h2><p>${esc(error.message)}</p></div>`;return;}
  posts=data||[];await loadProfiles(posts.map(post=>post.author_id));renderPosts();
}
function renderPosts(){
  const shown=posts.filter(post=>filter==='all'||post.category===filter);
  feed.innerHTML=shown.length?shown.map(post=>{const author=profile(post.author_id),reactions=post.community_post_reactions||[],counts=['❤','👏','💡'].map(emoji=>({emoji,count:reactions.filter(item=>item.emoji===emoji).length,own:reactions.some(item=>item.emoji===emoji&&item.user_id===user.id)})),canDelete=ownProfile?.role==='admin'||post.author_id===user.id;return `<article class="post-card ${post.pinned_at?'is-pinned':''}" data-post-id="${post.id}">${post.pinned_at?'<div class="post-pinned-label">ÉPINGLÉ PAR STOA</div>':''}<header>${avatar(author,post.author_id)}<div><button class="post-author-name" type="button" data-member-profile="${post.author_id}">${esc(author.display_name)}</button><span>${date(post.created_at)} · ${post.post_type==='stoa_editorial'?'Publication STOA':'Sujet membre'} · ${labels[post.category]}</span></div>${ownProfile?.role==='admin'||canDelete?`<div class="post-admin-actions">${ownProfile?.role==='admin'?`<button data-post-pin title="${post.pinned_at?'Désépingler':'Épingler'}">⌖</button>`:''}${canDelete?'<button data-post-delete title="Supprimer">×</button>':''}</div>`:''}</header><div class="post-copy"><h2>${esc(post.title)}</h2><p>${rich(post.content)}</p></div>${post.image_url?`<img class="post-image" src="${esc(post.image_url)}" alt="" loading="lazy">`:''}<footer><div class="post-reactions">${counts.map(item=>`<button class="${item.own?'active':''}" data-post-reaction="${item.emoji}">${item.emoji}${item.count?` <span>${item.count}</span>`:''}</button>`).join('')}</div><button class="post-comments-button" data-post-comments>${post.community_post_comments?.[0]?.count||0} réponse${Number(post.community_post_comments?.[0]?.count||0)>1?'s':''} <span>→</span></button></footer></article>`;}).join(''):'<div class="posts-empty"><span>✦</span><h2>Aucune publication ici pour le moment.</h2><p>Ouvrez le premier sujet de la communauté.</p></div>';
}
async function openThread(post){
  activePost=post;const {data:comments}=await supabase.from('community_post_comments').select('*').eq('post_id',post.id).order('created_at');await loadProfiles((comments||[]).map(item=>item.user_id));
  const author=profile(post.author_id);$('#post-thread-content').innerHTML=`<article class="post-thread-original"><span class="eyebrow">${labels[post.category]}</span><h2>${esc(post.title)}</h2><p>${rich(post.content)}</p><small>Par <button class="post-author-name" type="button" data-member-profile="${post.author_id}">${esc(author.display_name)}</button> · ${date(post.created_at)}</small></article><div class="post-thread-comments">${(comments||[]).map(comment=>{const member=profile(comment.user_id);return `<article>${avatar(member,comment.user_id)}<div><header><button class="post-author-name" type="button" data-member-profile="${comment.user_id}">${esc(member.display_name)}</button><time>${date(comment.created_at)}</time></header><p>${rich(comment.content)}</p></div></article>`;}).join('')||'<p class="thread-empty">Soyez la première personne à répondre.</p>'}</div>`;await window.STOACommunityNotifications?.markPostRead(post.id);if(!dialog.open)dialog.showModal();
}

function mentionToken(){const before=commentInput.value.slice(0,commentInput.selectionStart),match=before.match(/(^|\s)@([\p{L}\p{N}_.;-]*)$/u);return match?{query:match[2],start:before.length-match[2].length-1,end:before.length}:null;}
async function suggestMentions(){const token=mentionToken();if(!token){mentionSuggestions.hidden=true;return;}await loadAllProfiles();const query=norm(token.query),items=[...profiles.values()].filter(item=>item.username&&(norm(item.username).includes(query)||norm(item.display_name).includes(query))).slice(0,7);if(!items.length){mentionSuggestions.hidden=true;return;}mentionSuggestions.innerHTML=items.map(item=>`<button type="button" role="option" data-post-mention="${esc(item.username)}"><span class="suggestion-avatar">${esc((item.display_name||'S')[0].toUpperCase())}</span><span><strong>@${esc(item.username)}${item.id===user.id?' · vous':''}</strong><small>${esc(item.display_name)}</small></span></button>`).join('');mentionSuggestions.hidden=false;}
function applyMention(username){const token=mentionToken();if(!token)return;commentInput.setRangeText(`@${username} `,token.start,token.end,'end');mentionSuggestions.hidden=true;commentInput.focus();}
async function openMention(username){await loadAllProfiles();const member=[...profiles.values()].find(item=>norm(item.username)===norm(username));if(member)openMemberProfile(member.id);}

async function init(){
  user=(await supabase.auth.getSession()).data.session?.user;if(!user)return;ownProfile=(await supabase.from('profiles').select('role').eq('id',user.id).maybeSingle()).data;
  $('#post-composer').hidden=false;if(ownProfile?.role==='admin'){$('#post-editorial-wrap').hidden=false;$('#post-pinned-wrap').hidden=false;document.querySelector('[data-admin-only]').hidden=false;}await loadPosts();const requestedPost=new URLSearchParams(location.search).get('post');if(requestedPost){const post=posts.find(item=>item.id===requestedPost);if(post)await openThread(post);}
  room=supabase.channel('community-posts-feed').on('postgres_changes',{event:'*',schema:'public',table:'community_posts'},loadPosts).on('postgres_changes',{event:'*',schema:'public',table:'community_post_comments'},loadPosts).subscribe();
  addEventListener('pagehide',()=>{if(room)supabase.removeChannel(room)},{once:true});
}
$('#post-filters').addEventListener('click',event=>{const button=event.target.closest('[data-post-filter]');if(!button)return;filter=button.dataset.postFilter;$('#post-filters').querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));renderPosts();});
feed.addEventListener('click',async event=>{const mention=event.target.closest('[data-mention-username]');if(mention)return openMention(mention.dataset.mentionUsername);const member=event.target.closest('[data-member-profile]');if(member)return openMemberProfile(member.dataset.memberProfile);const card=event.target.closest('[data-post-id]');if(!card)return;const post=posts.find(item=>item.id===card.dataset.postId);if(event.target.closest('[data-post-comments]'))return openThread(post);const reaction=event.target.closest('[data-post-reaction]');if(reaction){const existing=post.community_post_reactions?.find(item=>item.emoji===reaction.dataset.postReaction&&item.user_id===user.id);if(existing)await supabase.from('community_post_reactions').delete().eq('id',existing.id);else await supabase.from('community_post_reactions').insert({post_id:post.id,user_id:user.id,emoji:reaction.dataset.postReaction});return loadPosts();}if(event.target.closest('[data-post-pin]')){await supabase.from('community_posts').update({pinned_at:post.pinned_at?null:new Date().toISOString()}).eq('id',post.id);return loadPosts();}if(event.target.closest('[data-post-delete]')){if(confirm('Supprimer définitivement cette publication ?')){const {error}=await supabase.rpc('delete_community_post',{p_post_id:post.id});if(error)return alert(`La publication n’a pas pu être supprimée : ${error.message}`);await loadPosts();}}});
async function uploadPostImage(file){if(!file)return null;if(file.size>8*1024*1024)throw new Error('L’image dépasse 8 Mo.');const extension=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'');const path=`community-posts/${user.id}/${crypto.randomUUID()}.${extension}`;const {error}=await supabase.storage.from('module-assets').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(error)throw error;return supabase.storage.from('module-assets').getPublicUrl(path).data.publicUrl;}
function clearPostImage(){const input=$('#post-image'),preview=$('#post-image-preview');input.value='';preview.hidden=true;preview.querySelector('img').removeAttribute('src');if(postImagePreviewUrl)URL.revokeObjectURL(postImagePreviewUrl);postImagePreviewUrl='';}
$('#post-image').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return clearPostImage();if(!file.type.startsWith('image/')){clearPostImage();$('#post-form-status').textContent='Choisissez un fichier image.';return;}if(postImagePreviewUrl)URL.revokeObjectURL(postImagePreviewUrl);postImagePreviewUrl=URL.createObjectURL(file);const preview=$('#post-image-preview');preview.querySelector('img').src=postImagePreviewUrl;preview.hidden=false;});
$('#post-image-remove').addEventListener('click',clearPostImage);
$('#post-form').addEventListener('submit',async event=>{event.preventDefault();const status=$('#post-form-status'),submit=event.currentTarget.querySelector('[type="submit"]'),isAdmin=ownProfile?.role==='admin',editorial=isAdmin&&$('#post-editorial').checked;submit.disabled=true;status.textContent='Publication…';let imageUrl=null;try{imageUrl=await uploadPostImage($('#post-image').files?.[0]);}catch(error){submit.disabled=false;status.textContent=`L’image n’a pas pu être envoyée : ${error.message}`;return;}const category=$('#post-category').value==='announcement'&&!isAdmin?'discussion':$('#post-category').value;const {error}=await supabase.from('community_posts').insert({author_id:user.id,post_type:editorial?'stoa_editorial':'member_topic',category,title:$('#post-title').value.trim(),content:$('#post-content').value.trim(),image_url:imageUrl,pinned_at:isAdmin&&$('#post-pinned').checked?new Date().toISOString():null});submit.disabled=false;status.textContent=error?error.message:'Publication ajoutée.';if(!error){event.currentTarget.reset();clearPostImage();loadPosts();}});
$('#post-comment-form').addEventListener('submit',async event=>{event.preventDefault();const content=$('#post-comment-content').value.trim();if(!content||!activePost)return;const {error}=await supabase.from('community_post_comments').insert({post_id:activePost.id,user_id:user.id,content});$('#post-comment-status').textContent=error?error.message:'Réponse publiée.';if(!error){$('#post-comment-content').value='';await openThread(activePost);loadPosts();}});
commentInput.addEventListener('input',suggestMentions);
commentInput.addEventListener('keydown',event=>{if(event.key==='Escape'&&!mentionSuggestions.hidden){event.preventDefault();mentionSuggestions.hidden=true;}});
mentionSuggestions.addEventListener('click',event=>{const button=event.target.closest('[data-post-mention]');if(button)applyMention(button.dataset.postMention);});
$('#post-thread-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
dialog.addEventListener('click',event=>{const mention=event.target.closest('[data-mention-username]');if(mention)return openMention(mention.dataset.mentionUsername);const member=event.target.closest('[data-member-profile]');if(member)openMemberProfile(member.dataset.memberProfile);});
document.addEventListener('click',event=>{if(!event.target.closest('.post-comment-composer-wrap'))mentionSuggestions.hidden=true;});
init();
